package de.igslandstuhl.database.attendance;
import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Clock;import java.util.Base64;
final class RotatingQrTokenService {static final long WINDOW_SECONDS=30;static final String PURPOSE="ATTENDANCE_LOCATION_V1";private final byte[] secret;private final Clock clock;
 RotatingQrTokenService(String s,Clock c){if(s==null||s.length()<32)throw new IllegalArgumentException("QR-Secret ist nicht sicher konfiguriert");secret=s.getBytes(StandardCharsets.UTF_8);clock=c;}
 String create(long id){long w=clock.instant().getEpochSecond()/WINDOW_SECONDS;String p=PURPOSE+"."+id+"."+w;return Base64.getUrlEncoder().withoutPadding().encodeToString(p.getBytes(StandardCharsets.UTF_8))+"."+sign(p);}
 long validate(String token){if(token==null||token.length()>512)throw invalid();String[] a=token.split("\\.",-1);if(a.length!=2)throw invalid();final String p;try{p=new String(Base64.getUrlDecoder().decode(a[0]),StandardCharsets.UTF_8);}catch(IllegalArgumentException e){throw invalid();}String[] v=p.split("\\.",-1);if(v.length!=3||!PURPOSE.equals(v[0])||!MessageDigest.isEqual(sign(p).getBytes(StandardCharsets.US_ASCII),a[1].getBytes(StandardCharsets.US_ASCII)))throw invalid();try{long id=Long.parseLong(v[1]),w=Long.parseLong(v[2]),now=clock.instant().getEpochSecond()/WINDOW_SECONDS;if(id<=0||w<now-1||w>now)throw invalid();return id;}catch(NumberFormatException e){throw invalid();}}
 private String sign(String p){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret,"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(p.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private static IllegalArgumentException invalid(){return new IllegalArgumentException("Dieser QR-Code ist nicht mehr gültig. Bitte scanne den aktuellen QR-Code am Raum erneut.");}}
